+{
+  velaclaw_msg_t msg;
+  char content[512];
+  int ret;
+
+  if (argc < 2)
+    {
+      printf("Usage: ask <message>\n");
+      return 1;
+    }
+
+  ask_join_args(argc, argv, content, sizeof(content));
+  if (content[0] == '\0')
+    {
+      printf("Usage: ask <message>\n");
+      return 1;
+    }
+
+  ret = ask_wait_agent_ready();
