  memset(&g_wifi, 0, sizeof(g_wifi));
  g_wifi.cb = cb;
  g_wifi.user_data = user_data;
  g_wifi.status = UI_DEMO_WIFI_STATUS_OFF;
  ui_demo_wifi_set_message_locked("WiFi 未开启");
  pthread_mutex_unlock(&g_wifi_lock);
}

