static void ui_demo_netinfo_async_cb(void *user_data)
{
  enum ui_demo_netinfo_event event =
    (enum ui_demo_netinfo_event)(uintptr_t)user_data;
  ui_demo_netinfo_event_cb_t cb;
  void *cb_user_data;

  pthread_mutex_lock(&g_netinfo_lock);
