+static int ui_demo_netinfo_decode_chunked(const char *src,
+                                          char *dst,
+                                          size_t dst_cap)
+{
+  const char *p = src;
+  size_t used = 0;
+
+  if (src == NULL || dst == NULL || dst_cap == 0)
+    {
+      return -EINVAL;
+    }
+
+  while (*p != '\0')
+    {
+      char *end = NULL;
+      unsigned long chunk_len;
+
+      while (*p == '\r' || *p == '\n')
+        {
+          p++;
+        }
+
+      chunk_len = strtoul(p, &end, 16);
+      if (end == p)
+        {
+          return -EINVAL;
+        }
+
+      while (*end != '\0' && *end != '\r' && *end != '\n')
+        {
+          end++;
+        }
+
+      if (end[0] == '\r' && end[1] == '\n')
+        {
+          p = end + 2;
+        }
+      else if (end[0] == '\n')
+        {
+          p = end + 1;
+        }
+      else
+        {
+          return -EINVAL;
+        }
+
+      if (chunk_len == 0)
+        {
+          dst[used] = '\0';
+          return OK;
+        }
+
+      if (used + chunk_len >= dst_cap)
+        {
+          return -ENOSPC;
+        }
+
+      memcpy(dst + used, p, chunk_len);
+      used += chunk_len;
+      p += chunk_len;
+
+      if (p[0] == '\r' && p[1] == '\n')
+        {
+          p += 2;
+        }
+      else if (p[0] == '\n')
+        {
+          p += 1;
+        }
+    }
+
+  return -EINVAL;
+}

